/*
 * Compile-time ordinal validation for a family known at the call site.
 * Evaluates to nonzero when `ordinal` is a valid variant of `family`:
 *
 *     FE_ENUMS_ORDINAL_VALID(Currency, ord)  // ord < FE_Currency_COUNT
 */
#define FE_ENUMS_ORDINAL_VALID(family, ordinal) \
    ((size_t)(ordinal) < (size_t)(FE_##family##_COUNT))

